const book=document.querySelector('[data-color-book]');
if(book){const pages=[...book.querySelectorAll('[data-book-page]')],buttons=[...book.querySelectorAll('[data-book-select]')];let current=0;const show=index=>{current=(index+pages.length)%pages.length;pages.forEach((page,i)=>page.hidden=i!==current);buttons.forEach((button,i)=>button.setAttribute('aria-pressed',String(i===current)));book.querySelector('[data-book-status]').textContent=buttons[current].textContent.trim()+' · '+(current+1)+' of '+pages.length;};buttons.forEach((button,i)=>button.addEventListener('click',()=>show(i)));book.querySelector('[data-book-prev]').addEventListener('click',()=>show(current-1));book.querySelector('[data-book-next]').addEventListener('click',()=>show(current+1));}
